class Section:
    def __init__(self, name):
        self.name = name
    def __enter__(self):
        print("start", self.name)
        return self
    def __exit__(self, exc_type, exc, tb):
        print("end", self.name)

with Section("A"):
    print("inside")

from contextlib import contextmanager

@contextmanager
def tag(name):
    print("<" + name + ">")
    try:
        yield
    finally:
        print("</" + name + ">")

with tag("b"):
    print("text")

