from contextlib import contextmanager

@contextmanager
def banner(title):
    print("== " + title + " ==")
    try:
        yield
    finally:
        print("== end ==")

with banner("Report"):
    print("body")

from contextlib import contextmanager
state = {"locked": False}

@contextmanager
def locked_mode():
    state["locked"] = True
    try:
        yield
    finally:
        state["locked"] = False

with locked_mode():
    print(state["locked"])
print(state["locked"])
try:
    with locked_mode():
        raise ValueError("x")
except ValueError:
    pass
print(state["locked"])

